126	\dcref{M:ch2:II.4}
127	For every $n$ not divisible by $\operatorname{char}k$, $n_X$ is surjective.
128	\source{mumford-abelian-varieties:page-0053}\source{mumford-abelian-varieties:page-0054}
129	\end{theorem}
130	\begin{proof}
131	The tangent space at $(0,0)$ splits as $T\oplus T$, and the differential of
132	$m$ is addition: $d(m)(t_1,t_2)=t_1+t_2$, since the restrictions to the two
133	summands are the identity. Induction gives $(dn_X)_0=n$ on $T$. Thus it is an
134	isomorphism when $\operatorname{char}k\nmid n$. If $n_X$ were not surjective,
135	the dimension theorem would give a nonzero tangent vector to
136	$n_X^{-1}(0)$ at $0$, contradicting injectivity of $(dn_X)_0$.
137	\end{proof}
138	
139	\begin{lemma}[Rigidity Lemma, Form I]
140	\label{mumford-lem-rigidity-form-I}
141	\lean{Mumford.GroupScheme.rigidity_lemma_of_geometricallyIntegral}
142	\dcref{M:ch2:II.4}
143	Let $X$ be complete, $Y,Z$ varieties, and $f:X\times Y\to Z$ a morphism such
144	that $f(X\times\{y_0\})=\{z_0\}$. Then $f=g\circ p_2$ for a morphism
145	$g:Y\to Z$.
146	\source{mumford-abelian-varieties:page-0054}
147	\leanok
148	\end{lemma}
149	\begin{proof}
150	Choose $x_0\in X$ and set $g(y)=f(x_0,y)$. Let $U$ be an affine neighborhood
151	of $z_0$, $F=Z-U$, and $G=p_2(f^{-1}(F))$. Since $X$ is complete, $G$ is
152	closed; since $y_0\notin G$, $V=Y-G$ is nonempty open. For $y\in V$, the
153	complete variety $X\times\{y\}$ maps into affine $U$, hence to one point.
154	Thus $f(x,y)=f(x_0,y)=g(p_2(x,y))$ on a nonempty open, and therefore everywhere.
155	\leanok
156	\end{proof}
157	
158	\begin{corollary}[Morphisms are homomorphisms up to translation]
159	\label{mumford-cor-morphism-translation}
160	\dcref{M:ch2:II.4}
161	If $X,Y$ are abelian varieties and $f:X\to Y$ is a morphism, then
162	$f(x)=h(x)+a$ for a homomorphism $h$ and $a\in Y$.
163	\source{mumford-abelian-varieties:page-0054}
164	\lean{Mumford.GroupScheme.exists_hom_comp_pointTranslation_of_isAbelianVariety_arbitraryField}
165	\leanok
166	\uses{mumford-lem-rigidity-form-I}
167	\end{corollary}
168	\begin{proof}
169	Replace $f$ by $f-f(0)$. The morphism
170	$\phi(x,y)=f(x+y)-f(y)-f(x)$ vanishes on both coordinate axes. Rigidity gives
171	$\phi=0$, so $f$ is a homomorphism.
172	\end{proof}
173	
174	\begin{corollary}[Second commutativity proof]
175	\label{mumford-cor-abelian-commutative}
176	\dcref{M:ch2:II.4}
177	An abelian variety is commutative.
178	\source{mumford-abelian-varieties:page-0055}
179	\lean{Mumford.GroupScheme.isCommMonObj_of_isAbelianVariety_via_rigidity}
180	\leanok
181	\uses{mumford-cor-morphism-translation}
182	\end{corollary}
183	\begin{proof}
184	The inverse map is a homomorphism by the preceding corollary. Hence
185	$(xy)^{-1}=x^{-1}y^{-1}=y^{-1}x^{-1}$, so $X$ is commutative.
186	\end{proof}
